cat > src/agent/resume.ts <<'EOF'
export const MAX_FAILURES = 3;

export function nextSteps(
  plan: { steps: { key: string; dependsOn: string[] }[] },
  events: { key: string; status: 'started' | 'done' | 'failed' }[],
): string[] {
  const done = new Set<string>();
  const failures = new Map<string, number>();
  for (const e of events) {
    if (e.status === 'done') done.add(e.key);
    else if (e.status === 'failed') failures.set(e.key, (failures.get(e.key) ?? 0) + 1);
  }
  return plan.steps
    .filter(
      (s) =>
        !done.has(s.key) &&
        (failures.get(s.key) ?? 0) < MAX_FAILURES &&
        s.dependsOn.every((d) => done.has(d)),
    )
    .map((s) => s.key);
}
EOF
cat > tests/resume.test.ts <<'EOF'
import { describe, expect, test } from 'bun:test';
import { nextSteps } from '../src/agent/resume';

const plan = {
  steps: [
    { key: 'a', dependsOn: [] },
    { key: 'b', dependsOn: ['a'] },
    { key: 'c', dependsOn: ['b'] },
    { key: 'd', dependsOn: [] },
  ],
};

describe('nextSteps', () => {
  test('fresh run returns steps with no unmet deps, in plan order', () => {
    expect(nextSteps(plan, [])).toEqual(['a', 'd']);
  });
  test('done steps are not repeated; dependents unlock', () => {
    expect(nextSteps(plan, [{ key: 'a', status: 'done' }])).toEqual(['b', 'd']);
  });
  test('started but unfinished step is returned again', () => {
    expect(nextSteps(plan, [{ key: 'a', status: 'started' }])).toEqual(['a', 'd']);
  });
  test('failed step is retried until 3 failures', () => {
    const f = (n: number) => Array.from({ length: n }, () => ({ key: 'a', status: 'failed' as const }));
    expect(nextSteps(plan, f(2))).toEqual(['a', 'd']);
    expect(nextSteps(plan, f(3))).toEqual(['d']);
  });
  test('dependents of an exhausted step are not returned', () => {
    const ev = Array.from({ length: 3 }, () => ({ key: 'b', status: 'failed' as const }));
    expect(nextSteps(plan, [{ key: 'a', status: 'done' }, ...ev])).toEqual(['d']);
  });
  test('done after earlier failures counts as done', () => {
    const ev = [
      { key: 'a', status: 'failed' as const },
      { key: 'a', status: 'started' as const },
      { key: 'a', status: 'done' as const },
    ];
    expect(nextSteps(plan, ev)).toEqual(['b', 'd']);
  });
  test('all done returns empty', () => {
    expect(nextSteps(plan, plan.steps.map((s) => ({ key: s.key, status: 'done' as const })))).toEqual([]);
  });
});
EOF
bun test tests/resume.test.ts 2>&1 | tail -8; bun run typecheck 2>&1 | tail -3; bun test 2>&1 | tail -5

